('00000000-0000-0000-0000-000000001112', 'CY-BIKE-HER-112', 'Hero Mountain Bike - 27.5in', 'hero-mountain-bike-27-5in', 'A sturdy 27.5-inch mountain bike with front suspension and wide tyres for trails and rough roads.', (SELECT id FROM brands WHERE name = 'Hero'), (SELECT id FROM categories WHERE name = 'Bike'), (SELECT id FROM sports WHERE name = 'Cycling'), 14.5, 'kg', 'ACTIVE', 1),
('00000000-0000-0000-0000-000000001113', 'CY-HELM-BTW-113', 'Btwin Cycling Helmet - Ventilated', 'btwin-cycling-helmet-ventilated', 'A ventilated helmet with an adjustable fit dial and a removable visor for all-round riding.', (SELECT id FROM brands WHERE name = 'Btwin'), (SELECT id FROM categories WHERE name = 'Helmet'), (SELECT id FROM sports WHERE name = 'Cycling'), 0.28, 'kg', 'ACTIVE', 1),
